import React, { RefObject } from 'react';

import { useOverlays } from './hooks/useOverlays.js';
import { WithChildren } from '../../../../core/types/with-children.js';
import { OverlaysContext } from '../../context/OverlaysContext.js';
import { OverlaysProps } from '../../types/overlays.js';
import { DivPlotLayout } from '../chart-grid/ChartGridRoot.js';

export interface ChartOverlaysProps extends WithChildren {
  tooltipContainerRef?: RefObject<HTMLDivElement>;
  onMouseMove?: (e: React.MouseEvent, newState: OverlaysProps) => void;
  onMouseEnter?: (e: React.MouseEvent, newState: OverlaysProps) => void;
  onMouseLeave?: (e: React.MouseEvent, newState: OverlaysProps) => void;
  onClick?: (e: React.MouseEvent) => void;
  onDoubleClick?: (e: React.MouseEvent) => void;
  onFocus?: (e: React.FocusEvent) => void;
  onBlur?: (e: React.FocusEvent) => void;
}

export const ChartOverlays = (props: ChartOverlaysProps) => {
  const {
    onMouseMove,
    onMouseEnter,
    onMouseLeave,
    onFocus,
    onBlur,
    onClick,
    onDoubleClick,
    children,
    tooltipContainerRef,
  } = props;

  const {
    handleMouseEnter,
    handleMouseMove,
    handleMouseOut,
    handleFocus,
    handleBlur,
    handleWheel,
    overlayRef,
    isInChartBounds,
    mousePosition,
    chartBounds,
    eventLocalPoint,
  } = useOverlays(onMouseMove, onMouseEnter, onMouseLeave, onFocus, onBlur);

  return (
    <OverlaysContext.Provider
      value={{
        isInChartBounds,
        mousePosition,
        chartBounds,
        eventLocalPoint,
        tooltipContainerRef,
        overlayRef,
      }}
    >
      <DivPlotLayout
        tabIndex={0}
        data-testid="overlays-wrapper"
        ref={overlayRef as RefObject<HTMLDivElement>}
        onClick={onClick}
        onMouseMove={handleMouseMove}
        onFocus={handleFocus}
        onBlur={handleBlur}
        onMouseEnter={handleMouseEnter}
        onMouseOut={handleMouseOut}
        onDoubleClick={onDoubleClick}
        onWheel={handleWheel}
      >
        {children}
      </DivPlotLayout>
    </OverlaysContext.Provider>
  );
};

ChartOverlays['displayName'] = 'ChartOverlays';
